/**
 * Mock API + static server for dashboard screenshots.
 *
 * Serves web/dist and answers the API surface src/api.ts touches with the last
 * live capture (scripts/livePayloads.ts, generated by capture-live.mjs) plus
 * deterministic synthetic screen/survey/heat rows and NEARUSDT candles, so the
 * dashboard renders realistically while the backend is stopped.
 *
 *   node scripts/mock-api.mjs [port]      # default 8799
 */
import { createServer } from 'node:http';
import { readFileSync, existsSync, statSync } from 'node:fs';
import { dirname, extname, join, normalize, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');
// vite.config.ts builds to ../backend/web/dist, outside web/ — mirror that.
const distCandidate = resolve(root, '..', 'backend', 'web', 'dist');
const dist = existsSync(join(distCandidate, 'index.html')) ? distCandidate : join(root, 'dist');
const port = Number(process.argv[2] ?? 8799);

// --- live capture: parse the TS module into JSON objects --------------------
const src = readFileSync(join(here, 'livePayloads.ts'), 'utf8');
const live = {};
for (const chunk of src.split('export const ').slice(1)) {
  const name = chunk.slice(0, chunk.indexOf(' = '));
  const start = chunk.indexOf(' = ') + 3;
  const end = chunk.lastIndexOf(' as const;');
  try {
    live[name] = JSON.parse(chunk.slice(start, end));
  } catch {
    live[name] = null;
  }
}

// --- deterministic synthetic data -------------------------------------------
let seed = 42;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;

const NOW = 1792112572000;
const ALERTS = Array.isArray(live.LIVE_KLINES_ALERTS) ? live.LIVE_KLINES_ALERTS : [];
const PRICE = ALERTS[0]?.price ?? 5.31;

const bars = [];
let close = PRICE * 0.995;
for (let i = 300; i > 0; i -= 1) {
  const t = NOW - i * 60_000;
  const drift = (rnd() - 0.5) * 0.001;
  const o = close;
  const c = o * (1 + drift);
  const h = Math.max(o, c) * (1 + rnd() * 0.0006);
  const l = Math.min(o, c) * (1 - rnd() * 0.0006);
  bars.push({ t, o, h, l, c, v: 800 + rnd() * 4200 });
  close = c;
}
const marks = ALERTS.map((a) => ({
  t: a.ts_ms,
  letter: a.kind === 'PUMP' ? 'P' : 'D',
  color: a.color ?? '#00e676',
  title: a.summary ?? a.kind,
}));

const screenSymbols = ['NEARUSDT', 'DOTUSDT', 'BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'ARBUSDT', 'CHIPUSDT', 'ERAUSDT', 'ALTUSDT', 'IOSTUSDT', 'XRPUSDT', 'DOGEUSDT'];
const kinds = ['PUMP', 'WATCH', 'BREAKOUT', 'REVERSAL_PUMP', 'WATCH', 'DUMP', 'WATCH', 'PUMP', 'WATCH', 'BREAKOUT', 'WATCH', 'REVERSAL_DUMP'];
const screenRows = screenSymbols.map((symbol, i) => ({
  symbol,
  kind: kinds[i],
  score: Math.round(90 - i * 6 + rnd() * 4),
  price: symbol === 'BTCUSDT' ? 96500 + rnd() * 200 : symbol === 'ETHUSDT' ? 3450 : +(PRICE * (0.4 + rnd() * 1.8)).toFixed(4),
  ret_5m: +((rnd() - 0.35) * 1.4).toFixed(3),
  ret_15m: +((rnd() - 0.35) * 2.2).toFixed(3),
  ret_60m: +((rnd() - 0.4) * 3.6).toFixed(3),
  ret_24h: +((rnd() - 0.45) * 9).toFixed(3),
  vol_ratio: +(1 + rnd() * 14).toFixed(2),
  vol_z: +((rnd() * 7) - 1).toFixed(2),
  quote_volume_24h: Math.round(2e7 + rnd() * 4e8),
  taker_buy_ratio: +(0.35 + rnd() * 0.4).toFixed(3),
  close_position: +(rnd()).toFixed(3),
  range_pct: +(0.4 + rnd() * 3).toFixed(2),
  atr_pct: +(0.05 + rnd() * 0.3).toFixed(3),
  from_24h_high: -((rnd()) * 6).toFixed(3),
  from_24h_low: +((rnd()) * 6).toFixed(3),
  bars_since_extreme: Math.round(rnd() * 120),
  reasons: ['16.1x flow burst', 'taker skew +0.12', 'range position 0.81'].slice(0, 1 + Math.floor(rnd() * 3)),
}));

const surveySetups = screenRows.slice(0, 4).map((r, i) => ({
  symbol: r.symbol,
  side: r.kind === 'DUMP' || r.kind === 'REVERSAL_DUMP' ? 'short' : 'long',
  score: r.score,
  plan: {
    entry: r.price,
    stop: +(r.price * (r.side === 'short' ? 1.012 : 0.988)).toFixed(6),
    unit_size: 1,
    units: 2 + i,
    total_notional: Math.round(400 + rnd() * 2400),
  },
}));

const heatRows = screenRows.map((r) => ({
  symbol: r.symbol,
  heat: Math.round(r.score),
  components: { flow: rnd(), move: rnd(), trend: rnd(), level: rnd(), range: rnd() },
  reasons: r.reasons,
}));

// --- server -----------------------------------------------------------------
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml', '.png': 'image/png', '.json': 'application/json' };

const server = createServer((req, res) => {
  const url = new URL(req.url ?? '/', `http://127.0.0.1:${port}`);
  const path = url.pathname;
  const sendJson = (obj, code = 200) => {
    res.writeHead(code, { 'content-type': 'application/json' });
    res.end(JSON.stringify(obj));
  };

  if (path === '/api/events') {
    res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache', connection: 'keep-alive' });
    res.write(': ok\n\n');
    // Headless screenshots need the page to reach idle: hold the stream briefly
    // (one retry at most), then end it. The app reconnects against a live backend.
    setTimeout(() => res.end(), 700);
    return;
  }
  if (path === '/api/flow') return sendJson(live.LIVE_FLOW_SPLIT ?? { type: 'flow' });
  if (path === '/api/outlook') {
    const sym = url.searchParams.get('symbol') ?? 'DOTUSDT';
    const o = structuredClone(live.LIVE_OUTLOOK ?? {});
    o.symbol = sym;
    return sendJson(o);
  }
  if (path === '/api/flow/history') return sendJson(live.LIVE_FLOW_HISTORY ?? { type: 'flow_history', bins: [] });
  if (path === '/api/klines') {
    return sendJson({
      type: 'klines',
      symbol: url.searchParams.get('symbol') ?? 'NEARUSDT',
      interval: url.searchParams.get('interval') ?? '1m',
      ts_ms: NOW,
      bars,
      marks,
      latest: { close: PRICE },
      alerts: ALERTS,
    });
  }
  if (path === '/api/screen') return sendJson({ type: 'screen', ts_ms: NOW, symbols_scanned: 127, rows: screenRows });
  if (path === '/api/survey') {
    return sendJson({
      type: 'survey',
      ts_ms: NOW,
      equity: 100000,
      timeframes: ['1m', '5m', '15m'],
      symbols_scanned: 127,
      symbols_with_data: 118,
      budget: { total_units: 12, long_units: 7, short_units: 5, total_notional: 9600, total_risk: 640, positions: 6, rejected: 3 },
      setups: surveySetups,
      exit_signals: [],
    });
  }
  if (path === '/api/heat') return sendJson({ type: 'heat', ts_ms: NOW, rows: heatRows });
  if (path === '/api/colors') return sendJson(live.LIVE_COLORS ?? {});
  if (path === '/api/screen/refresh' || path === '/api/survey/refresh') return sendJson({}, 204);
  if (path === '/api/alerts' && req.method === 'DELETE') return sendJson({}, 204);
  if (path.startsWith('/api/')) return sendJson({ error: 'mock: not found' }, 404);

  // static dist
  const file = normalize(join(dist, path === '/' ? 'index.html' : path));
  if (!file.startsWith(dist) || !existsSync(file) || !statSync(file).isFile()) {
    res.writeHead(404);
    res.end('not found');
    return;
  }
  res.writeHead(200, { 'content-type': MIME[extname(file)] ?? 'application/octet-stream' });
  res.end(readFileSync(file));
});

server.listen(port, '127.0.0.1', () => console.log(`mock dashboard on http://127.0.0.1:${port}`));
